// The 10 Trex markets, picked 2026-09-29 from a cost-inclusive test of 22 Capital.com markets.
// Yahoo-style keys; the local price server maps them to Capital.com: GC=F->GOLD, BTC-USD->BTCUSD, GBPUSD=X->GBPUSD,
// ETH-USD->ETHUSD, CAD=X->USDCAD, ^GDAXI->DE40, CHF=X->USDCHF, BZ=F->OIL_BRENT, CL=F->OIL_CRUDE, HG=F->COPPER.
const symbols = ['GC=F', 'BTC-USD', 'GBPUSD=X', 'ETH-USD', 'CAD=X', '^GDAXI', 'CHF=X', 'BZ=F', 'CL=F', 'HG=F'];
return symbols.map(symbol => ({ json: { symbol } }));

// Trex Universal scanner - same rules and default settings as the TradingView strategy "Trex Universal".
// Checks closed 5-minute candles from Capital.com (via the local T-REX trigger server; Yahoo/yfinance fallback) and sends each NEW BUY/SELL to Telegram (once).
const P = { len: 20, win: 3, rr: 2, buf: 0.25, maxRisk: 2, cool: 3, flip: false, useTrend: true, emaLen: 200, useVol: false, volMult: 1.3, tfMin: 5 };
const NAMES = { 'CL=F': 'Crude Oil', 'BZ=F': 'Brent Oil', 'GC=F': 'Gold', 'SI=F': 'Silver', 'HG=F': 'Copper', 'NG=F': 'Natural Gas', 'BTC-USD': 'Bitcoin', 'ETH-USD': 'Ethereum', 'GBPUSD=X': 'GBP/USD', 'EURUSD=X': 'EUR/USD', 'CAD=X': 'USD/CAD', 'CHF=X': 'USD/CHF', 'JPY=X': 'USD/JPY', 'AUDUSD=X': 'AUD/USD', '^GDAXI': 'Germany 40', '^FTSE': 'UK 100', 'ES=F': 'US 500', 'NQ=F': 'US Tech 100', 'YM=F': 'US Wall Street 30' };
const manual = ['test', 'manual'].includes($execution.mode);
const store = $getWorkflowStaticData('global');
if (!store.last) store.last = {};
const nowSec = Date.now() / 1000;
const num = v => String(Number(Number(v).toPrecision(7)));
const utc = t => new Date(t * 1000).toISOString().slice(0, 16).replace('T', ' ') + ' UTC';

function scan(bars) {
  const n = bars.length;
  const atr = new Array(n).fill(null), ema = new Array(n).fill(null), volAvg = new Array(n).fill(null);
  let trSum = 0;
  for (let i = 0; i < n; i++) {
    const b = bars[i];
    const tr = i === 0 ? b.h - b.l : Math.max(b.h - b.l, Math.abs(b.h - bars[i - 1].c), Math.abs(b.l - bars[i - 1].c));
    if (i < 14) { trSum += tr; if (i === 13) atr[i] = trSum / 14; }
    else atr[i] = (atr[i - 1] * 13 + tr) / 14;
  }
  const a = 2 / (P.emaLen + 1);
  for (let i = 0; i < n; i++) ema[i] = i === 0 ? bars[i].c : a * bars[i].c + (1 - a) * ema[i - 1];
  let vs = 0;
  for (let i = 0; i < n; i++) { vs += bars[i].v; if (i >= 20) vs -= bars[i - 20].v; if (i >= 19) volAvg[i] = vs / 20; }
  let upLvl = null, upExt = null, upBar = null, dnLvl = null, dnExt = null, dnBar = null, lastSig = null;
  let pos = 0, stopPx = null, tgtPx = null, pending = null;
  const sigs = [];
  for (let i = 0; i < n; i++) {
    const b = bars[i];
    // fills during this candle: pending entry at the open, then stop / target
    if (pending) { pos = pending.side; stopPx = pending.sl; tgtPx = pending.tp; pending = null; }
    if (pos !== 0) {
      const hitStop = pos > 0 ? b.l <= stopPx : b.h >= stopPx;
      const hitTgt = pos > 0 ? b.h >= tgtPx : b.l <= tgtPx;
      if (hitStop || hitTgt) pos = 0;
    }
    if (i < P.len || atr[i] === null) continue;
    let hiRef = -Infinity, loRef = Infinity;
    for (let k = i - P.len; k < i; k++) { if (bars[k].h > hiRef) hiRef = bars[k].h; if (bars[k].l < loRef) loRef = bars[k].l; }
    if (b.h > hiRef) {
      if (upBar === null || i - upBar > P.win) { upLvl = hiRef; upExt = b.h; } else upExt = Math.max(upExt, b.h);
      upBar = i;
    }
    if (b.l < loRef) {
      if (dnBar === null || i - dnBar > P.win) { dnLvl = loRef; dnExt = b.l; } else dnExt = Math.min(dnExt, b.l);
      dnBar = i;
    }
    const gapOk = lastSig === null || i - lastSig > P.cool;
    const posOk = P.flip || pos === 0;
    const volOk = !P.useVol || (volAvg[i] !== null && b.v > volAvg[i] * P.volMult);
    const sell = upBar !== null && i - upBar <= P.win && b.c < upLvl && b.c < b.o && volOk && gapOk && posOk && pos >= 0 && (!P.useTrend || b.c < ema[i]);
    const buy = dnBar !== null && i - dnBar <= P.win && b.c > dnLvl && b.c > b.o && volOk && gapOk && posOk && pos <= 0 && (!P.useTrend || b.c > ema[i]);
    if (sell) {
      const sl = upExt + P.buf * atr[i], risk = sl - b.c;
      if (risk > 0 && risk <= P.maxRisk * atr[i]) {
        const tp = b.c - P.rr * risk;
        pending = { side: -1, sl, tp }; upBar = null; lastSig = i;
        sigs.push({ t: b.t, signal: 'SELL', price: b.c, sl, tp });
      }
    }
    if (buy) {
      const sl = dnExt - P.buf * atr[i], risk = b.c - sl;
      if (risk > 0 && risk <= P.maxRisk * atr[i]) {
        const tp = b.c + P.rr * risk;
        pending = { side: 1, sl, tp }; dnBar = null; lastSig = i;
        sigs.push({ t: b.t, signal: 'BUY', price: b.c, sl, tp });
      }
    }
  }
  return sigs;
}

const out = [];
const lines = [];
for (const item of $input.all()) {
  const res = item.json && item.json.chart && item.json.chart.result && item.json.chart.result[0];
  if (!res || !res.timestamp || !res.indicators) {
    const e = item.json && item.json.error;
    lines.push('⚠️ no data' + (e ? ' (' + (e.status || e.httpCode || e.message || 'error') + ')' : ''));
    continue;
  }
  const sym = res.meta.symbol;
  const name = NAMES[sym] || sym;
  const q = res.indicators.quote[0];
  const bars = [];
  for (let k = 0; k < res.timestamp.length; k++) {
    const t = res.timestamp[k];
    if (q.open[k] == null || q.high[k] == null || q.low[k] == null || q.close[k] == null) continue;
    if (t + P.tfMin * 60 > nowSec + 5) continue; // candle still forming
    bars.push({ t, o: q.open[k], h: q.high[k], l: q.low[k], c: q.close[k], v: (q.volume && q.volume[k]) || 0 });
  }
  if (bars.length < 250) { lines.push('⚠️ ' + name + ': only ' + bars.length + ' candles'); continue; }
  const sigs = scan(bars);
  const last = bars[bars.length - 1];
  const s = sigs.length ? sigs[sigs.length - 1] : null;
  if (manual) {
    lines.push('• ' + name + ' [' + sym + ']: ' + bars.length + ' candles, last close ' + utc(last.t + 300) + ', ' + sigs.length + ' signals in ' + Math.max(1, Math.round((last.t - bars[0].t) / 86400)) + ' days' + (s ? ', latest ' + s.signal + ' ' + utc(s.t + 300) : '') + ', source ' + (res.meta.source || 'yahoo'));
    continue;
  }
  const fresh = s && s.t === last.t && nowSec - (last.t + P.tfMin * 60) < 15 * 60;
  if (fresh && store.last[sym] !== s.t) {
    store.last[sym] = s.t;
    const icon = s.signal === 'BUY' ? '🟢' : '🔴';
    out.push({ json: { text: [icon + ' ' + s.signal + '  ' + name + ' [' + sym + ']', 'Timeframe: 5m', 'Entry: ' + num(s.price), 'Stop loss: ' + num(s.sl), 'Take profit: ' + num(s.tp), 'Trex Universal (n8n) · ' + utc(s.t + 300)].join('\n'), signal: s.signal, ticker: sym, name, price: s.price, sl: s.sl, tp: s.tp, time: utc(s.t + 300), source: res.meta.source || 'yahoo' } });
  }
}
if (manual) return [{ json: { text: ['🧪 Trex scanner test (not a trade signal)'].concat(lines, ['Live alerts will arrive here for each new BUY/SELL.']).join('\n'), test: true } }];
return out;

// Trex alert card for Telegram (HTML): name, BUY/SELL, entry, target + Hermes one-word verdict.
// Prices come from Capital.com via the local trigger server; a warning line appears only if Yahoo was used instead.
const sigs = $('Trex Signals').all();
const quotes = $('Capital.com quote').all();
// Skip alerts that are too expensive to trade: Capital.com spread above 20% of the stop distance, or market not open.
const MAX_SPREAD_OF_STOP = 0.2;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const px = v => {
  const n = Number(v);
  if (!isFinite(n)) return esc(v);
  if (Math.abs(n) >= 1000) return n.toLocaleString('en-US', { maximumFractionDigits: 2 });
  return Number(n.toPrecision(Math.abs(n) >= 10 ? 5 : 6)).toLocaleString('en-US', { maximumFractionDigits: 6 });
};
const LINE = '━━━━━━━━━━━━━━';
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const VERDICT = { TAKE: '✅ TAKE', CAUTION: '⚠️ CAUTION', SKIP: '⛔ SKIP' };
const reply = r => {
  const c = r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content;
  return typeof c === 'string' ? c.trim() : '';
};
return $input.all().map((item, i) => {
  const s = (sigs[i] || sigs[0]).json;
  const ai = reply(item.json);
  const m = ai.match(/verdict\W*(TAKE|CAUTION|SKIP)/i) || ai.match(/\b(TAKE|CAUTION|SKIP)\b/);
  const verdict = m ? VERDICT[m[1].toUpperCase()] : '';
  if (s.test) {
    const lines = String(s.text).split('\n');
    const rows = lines
      .map(l => l.match(/^• (.+?) \[.+?\]: .*?(\d+) signals in \d+ days, latest (BUY|SELL) \d{4}-(\d\d)-(\d\d) (\d\d:\d\d) UTC/))
      .filter(Boolean)
      .map(r => (r[3] === 'BUY' ? '🟢' : '🔴') + ' <b>' + esc(r[1]) + '</b>  ·  last ' + r[3] + ' ' + r[5] + ' ' + MON[+r[4] - 1] + ' ' + r[6] + ' UTC');
    const srcs = lines.map(l => (l.match(/, source (\S+)$/) || [])[1]).filter(Boolean);
    const feed = srcs.length && srcs.every(x => x === 'capital.com')
      ? '💱 Prices: <b>Capital.com live</b>'
      : '⚠️ Prices: <b>Yahoo</b> (Capital.com not connected)';
    const text = ['🧪 <b>TREX SCANNER · TEST</b>', LINE].concat(rows, [LINE, feed,
      ai ? '🤖 AI brain: <b>✅ online</b>' : '🤖 AI brain: <b>⚠️ not answering</b>',
      '<i>Live BUY / SELL alerts will arrive here.</i>']).join('\n');
    return { json: { text } };
  }
  const q = (quotes[i] && quotes[i].json) || {};
  const risk = Math.abs(Number(s.price) - Number(s.sl));
  if (q.status && q.status !== 'TRADEABLE') return null;
  if (q.spread != null && risk > 0 && Number(q.spread) / risk > MAX_SPREAD_OF_STOP) return null;
  const buy = String(s.signal).toUpperCase() === 'BUY';
  const lines = [
    (buy ? '🟢' : '🔴') + ' <b>' + (buy ? 'BUY' : 'SELL') + '  ·  ' + esc(s.name || s.ticker) + '</b>',
    LINE,
    '▶️ Entry:  <b>' + px(s.price) + '</b>',
    '🎯 Target:  <b>' + px(s.tp) + '</b>',
    LINE,
    verdict ? '🤖 AI check:  <b>' + verdict + '</b>' : '🤖 AI check:  <i>unavailable</i>',
  ];
  if (s.source && s.source !== 'capital.com') lines.push('⚠️ <i>Yahoo price - Capital.com feed offline</i>');
  return { json: { text: lines.join('\n'), signal: s.signal, ticker: s.ticker, name: s.name, price: s.price, sl: s.sl, tp: s.tp, time: s.time, source: s.source, verdict: m ? m[1].toUpperCase() : null, spread: q.spread ?? null } };
}).filter(Boolean);

const control = $input.first()?.json ?? {};
if (control.enabled !== true) return [];
return [{ json: { scanner_enabled: true } }];
